def isPathCrossing(path: str) -> bool:
    # Start at (0, 0) and add origin to visited set
    x, y = 0, 0
    visited = set()
    visited.add((x, y))
    for move in path:
        if move == 'N':
            y += 1
        elif move == 'S':
            y -= 1
        elif move == 'E':
            x += 1
        elif move == 'W':
            x -= 1
        # Check if we have been to this coordinate before
        coord = (x, y)
        if coord in visited:
            return True
        visited.add(coord)
    return False
